insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-so-204","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A flask contains 3.0 g of a non-volatile solute ($M = 60$) together with 117 g of a solvent ($M = 78$). Relative lowering of vapour pressure is nearest","options":["0.032","0.050","0.20","0.967"],"answer_index":0,"explanation":"$n_B = 0.050$, $n_A = 1.50$, so $x_B = 0.050 / 1.55 \\approx 0.032 = (p^\\circ - p)/p^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"relative-lowering"},{"id":"che-so-205","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A non-volatile solute causes the boiling point of a liquid to","options":["rise","fall","stay fixed","equal the freezing point"],"answer_index":0,"explanation":"The solution must be hotter before its vapour pressure reaches the external pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-206","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The molal boiling-point elevation constant $K_b$ is also called the","options":["ebullioscopic constant","cryoscopic constant","Henry constant","Rydberg constant"],"answer_index":0,"explanation":"$K_b$ is the ebullioscopic (boiling-point) constant of the solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-207","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"$\\Delta T_b$ for a dilute non-electrolyte solution is proportional to","options":["the molality of the solute","the molarity only","the mole fraction of solvent only","the charge of the solute"],"answer_index":0,"explanation":"The working relation is $\\Delta T_b = K_b m$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-208","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"$K_b$ is a characteristic of","options":["the solvent","the chemical identity of the solute","the volume of the flask","the colour of the solution"],"answer_index":0,"explanation":"Each solvent has its own molal elevation constant, independent of the non-electrolyte used.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-209","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Boiling point rises because the solution must be heated until its","options":["vapour pressure again equals the external pressure","freezing point equals 0 °C","osmotic pressure vanishes","$K_H$ is zero"],"answer_index":0,"explanation":"A non-volatile solute lowers p, so a higher T is needed to restore p = 1 atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-210","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A convenient unit of $K_b$ is","options":["K kg mol⁻¹","K L mol⁻¹","atm kg mol⁻¹","J mol⁻¹"],"answer_index":0,"explanation":"$\\Delta T_b = K_b m$ with m in mol kg⁻¹, so $K_b$ has unit K kg mol⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-211","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For water, the usual textbook $K_b$ is about","options":["0.52 K kg mol⁻¹","1.86 K kg mol⁻¹","0.0821 L atm K⁻¹ mol⁻¹","13.6 eV"],"answer_index":0,"explanation":"The ebullioscopic constant of water is 0.512 K kg mol⁻¹ (often rounded to 0.52).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-212","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molar mass of a non-volatile solute follows from $\\Delta T_b$ if one also knows","options":["$K_b$ and the masses (or molality)","only the colour of the solution","only $K_H$","only the density of air"],"answer_index":0,"explanation":"$m = \\Delta T_b / K_b$ and $m = (w_B / M_B) / w_A$ together give $M_B$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-213","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Elevation of boiling point is classified as a","options":["colligative property","chemical property of the solute","nuclear property","surface property only"],"answer_index":0,"explanation":"It depends on the number of solute particles, not on their identity (for a non-electrolyte).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-214","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Between two dilute aqueous non-electrolytes, the larger boiling-point elevation belongs to the solution of","options":["higher molality","lower molality","smaller $K_b$","zero mole fraction"],"answer_index":0,"explanation":"$\\Delta T_b = K_b m$ with the same $K_b$ (water), so the more molal solution boils higher.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-215","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 1 molal aqueous non-electrolyte, taking $K_b = 0.52$ K kg mol⁻¹, is expected to boil near","options":["100.52 °C","98.14 °C","100.00 °C","0.52 °C"],"answer_index":0,"explanation":"$\\Delta T_b = 0.52$ K, so the boiling point is about 100.52 °C at 1 atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation"},{"id":"che-so-216","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Glucose at 0.50 mol kg⁻¹ in water ($K_b = 0.512$ K kg mol⁻¹) elevates the boiling point by","options":["0.256 K","0.512 K","1.02 K","0.128 K"],"answer_index":0,"explanation":"$\\Delta T_b = 0.512 \\times 0.50 = 0.256$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation"},{"id":"che-so-217","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solution boils 0.208 °C above the pure solvent. If $K_b = 0.52$ K kg mol⁻¹, the molality is","options":["0.40 m","0.208 m","2.5 m","0.52 m"],"answer_index":0,"explanation":"$m = \\Delta T_b / K_b = 0.208 / 0.52 = 0.40$ mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation"},{"id":"che-so-218","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Urea 3.0 g (60 g mol⁻¹) in 250 g water ($K_b = 0.52$ K kg mol⁻¹) gives $\\Delta T_b$ of","options":["0.104 K","0.52 K","0.208 K","1.04 K"],"answer_index":0,"explanation":"m = (3.0/60) / 0.250 = 0.20 mol kg⁻¹; $\\Delta T_b = 0.52 \\times 0.20 = 0.104$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation"},{"id":"che-so-219","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Solvent X has $K_b$ twice that of water. The same molal non-electrolyte in X, compared with water, shows $\\Delta T_b$ that is","options":["twice as large","half as large","equal","zero"],"answer_index":0,"explanation":"$\\Delta T_b$ scales directly with $K_b$ at fixed molality.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation"},{"id":"che-so-220","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A non-volatile solute of molar mass 180 g mol⁻¹, 9.0 g, in 200 g of a solvent ($K_b = 2.5$ K kg mol⁻¹) raises the boiling point by","options":["0.625 K","2.5 K","0.25 K","1.25 K"],"answer_index":0,"explanation":"n = 0.050 mol in 0.200 kg, so m = 0.25 mol kg⁻¹ and $\\Delta T_b = 2.5 \\times 0.25 = 0.625$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation"},{"id":"che-so-221","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Fully ionised KCl (i = 2) at 0.10 mol kg⁻¹ in water ($K_b = 0.52$ K kg mol⁻¹) produces a boiling-point elevation of","options":["0.104 K","0.052 K","0.208 K","0.52 K"],"answer_index":0,"explanation":"$\\Delta T_b = i K_b m = 2 \\times 0.52 \\times 0.10 = 0.104$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"boiling-elevation"},{"id":"che-so-222","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.20 m Na2SO4 solution is 80% dissociated. Taking three ions per formula unit, $K_b = 0.512$ K kg mol⁻¹, $\\Delta T_b$ is nearest","options":["0.27 K","0.10 K","0.51 K","0.80 K"],"answer_index":0,"explanation":"$i = 1 + (3 - 1)(0.80) = 2.60$; $\\Delta T_b = 2.60 \\times 0.512 \\times 0.20 \\approx 0.27$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"boiling-elevation"},{"id":"che-so-223","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Adding a non-volatile solute to a solvent","options":["lowers the freezing point","raises the freezing point","leaves the freezing point unchanged","equals the boiling point"],"answer_index":0,"explanation":"The solid solvent is in equilibrium with a solution of lower chemical potential, so the freezing point falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-so-204","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-205","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-206","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-207","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-208","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-209","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-210","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-211","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-212","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-213","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-214","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-215","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-216","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-217","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-218","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-219","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-220","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-221","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-222","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-223","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
